-- =====================================================================
-- TermsConditions_Seed.sql   (2026-11-14)
-- ---------------------------------------------------------------------
-- Common Terms & Conditions, English + Bangla, for every operation :
--   Sales Invoice, Sales Quotation, Booking, Purchase Order
--   (each for MB = Motor Bike, SP = Spare Parts, AC = Accessories)
--
-- For each operation, ONE set is added : Code TC-nnnn (next free),
-- Title "<operation> <next number>", Active, and the Default when
-- the operation has no Default yet.
-- An operation that already has a live (not deleted) set is
-- SKIPPED, so your own sets are never touched and the script is
-- safe to run again.
--
-- The Bangla text is written as U&'\XXXX' escapes so this file
-- stays ASCII; the database (UTF8) stores real Bangla.
--
-- Run the whole script (F5) on AppCoreERP_Studio, after
-- TermsConditions_Engine.sql. Edit the lines afterwards on
-- Settings > General Settings > Terms & Conditions.
-- ASCII only.
-- =====================================================================

CREATE OR REPLACE FUNCTION pg_temp.tc_seed
(
    p_operation text,
    p_name      text,
    p_en        text[],
    p_bn        text[]
)
RETURNS void
LANGUAGE plpgsql
AS $fn$
DECLARE
    v_no      int;
    v_title   int;
    v_default boolean;
    v_set     bigint;
    i         int;
BEGIN
    IF EXISTS (SELECT 1 FROM public."TermsConditionSets"
               WHERE "OperationCode" = p_operation AND NOT "IsDeleted") THEN
        RAISE NOTICE '% : has a set already, skipped.', p_name;
        RETURN;
    END IF;

    -- next code over all sets (deleted ones count, never reused)
    SELECT COALESCE(MAX(substring("Code" FROM 4)::int), 0) + 1 INTO v_no
    FROM   public."TermsConditionSets"
    WHERE  "Code" ~ '^TC-[0-9]+$';

    -- next title number of this operation (as the page does)
    SELECT COALESCE(MAX(substring("Title" FROM length(p_name) + 2)::int), 0) + 1 INTO v_title
    FROM   public."TermsConditionSets"
    WHERE  "OperationCode" = p_operation
    AND    "Title" ~ ('^' || regexp_replace(p_name, '([^A-Za-z0-9 ])', '\\\1', 'g') || ' [0-9]+$');

    v_default := NOT EXISTS (SELECT 1 FROM public."TermsConditionSets"
                             WHERE "OperationCode" = p_operation
                             AND "IsDefault" AND "IsActive" AND NOT "IsDeleted");

    INSERT INTO public."TermsConditionSets"
        ("Code", "Title", "OperationCode", "IsDefault", "Note",
         "IsActive", "IsDeleted", "CreatedBy", "CreatedDate")
    VALUES
        ('TC-' || lpad(v_no::text, 4, '0'), p_name || ' ' || v_title, p_operation, v_default,
         'Common terms (seed 2026-11-14) : edit to suit.',
         true, false, 1, now())
    RETURNING "TermsConditionSetId" INTO v_set;

    FOR i IN 1 .. array_length(p_en, 1) LOOP
        INSERT INTO public."TermsConditionLines"
            ("TermsConditionSetId", "LineNo", "TextEn", "TextBn")
        VALUES
            (v_set, i, p_en[i], COALESCE(p_bn[i], ''));
    END LOOP;

    RAISE NOTICE '% : TC-% added with % lines%.', p_name, lpad(v_no::text, 4, '0'),
        array_length(p_en, 1), CASE WHEN v_default THEN ' (Default)' ELSE '' END;
END
$fn$;

