-- Check (run on its own)
-- ------------------------------------------------------------
SELECT s."Code", s."Title", s."IsDefault", COUNT(l.*) AS "Lines"
FROM   public."TermsConditionSets" s
LEFT JOIN public."TermsConditionLines" l ON l."TermsConditionSetId" = s."TermsConditionSetId"
WHERE  NOT s."IsDeleted"
GROUP  BY s."TermsConditionSetId", s."Code", s."Title", s."IsDefault"
ORDER  BY s."Code";
